alter table public.accounts enable row level security;
alter table public.files enable row level security;
alter table public.file_shares enable row level security;

create policy accounts_select on public.accounts
  for select to authenticated
  using (user_id = auth.uid());

create policy files_select on public.files
  for select to authenticated
  using (
    owner_id = auth.uid()
    or exists (
      select 1
      from public.file_shares fs
      where fs.file_id = files.id
        and fs.shared_with = auth.uid()
        and (fs.expires_at is null or fs.expires_at > now())
    )
  );

create policy files_insert on public.files
  for insert to authenticated
  with check (owner_id = auth.uid());

create policy files_update on public.files
  for update to authenticated
  using (owner_id = auth.uid())
  with check (owner_id = auth.uid());

create policy files_delete on public.files
  for delete to authenticated
  using (owner_id = auth.uid());

create policy file_shares_select on public.file_shares
  for select to authenticated
  using (
    file_id in (
      select f.id
      from public.files f
      where f.owner_id = auth.uid()
    )
    or shared_with = auth.uid()
  );

create policy file_shares_insert on public.file_shares
  for insert to authenticated
  with check (
    file_id in (
      select f.id
      from public.files f
      where f.owner_id = auth.uid()
    )
    and shared_with <> auth.uid()
  );

create policy file_shares_update on public.file_shares
  for update to authenticated
  using (
    file_id in (
      select f.id
      from public.files f
      where f.owner_id = auth.uid()
    )
  )
  with check (
    file_id in (
      select f.id
      from public.files f
      where f.owner_id = auth.uid()
    )
  );

create policy file_shares_delete on public.file_shares
  for delete to authenticated
  using (
    file_id in (
      select f.id
      from public.files f
      where f.owner_id = auth.uid()
    )
  );
