```sql
alter table public.finance_staff enable row level security;
alter table public.invoices enable row level security;

create or replace function public.is_finance_staff()
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.finance_staff
    where user_id = auth.uid()
  );
$$;

create or replace function public.invoice_creator()
returns uuid
language sql
stable
as $$
  select coalesce((select created_by from public.invoices where id = coalesce(current_setting('request.invoice', true), '')::bigint), auth.uid());
$$;

create or replace function public.invoice_status()
returns text
language sql
stable
as $$
  select coalesce(
    (select status from public.invoices where id = coalesce(current_setting('request.invoice', true), '')::bigint),
    ''
  );
$$;

create or replace function public.invoice_readable()
returns boolean
language sql
as $$
  select (select public.is_finance_staff())
     or public.invoice_creator() = auth.uid();
$$;

create or replace function public.invoice_can_write()
returns boolean
language sql
as $$
  select public.invoice_readable()
     and public.invoice_status() = 'draft';
$$;

create or replace function public.invoice_before_insert()
returns trigger
language plpgsql
as $$
begin
  if public.is_finance_staff() and auth.uid() is distinct from new.created_by
     or not public.is_finance_staff() and new.created_by is distinct from auth.uid()
     or not public.invoice_can_write() and new.status is distinct from 'draft'
     or new.created_by is distinct from auth.uid()
  then
    raise exception 'invalid invoice insert';
  end if;

  new.created_by := auth.uid();
  new.status := 'draft';

  return new;
end;
$$;

create or replace function public.invoice_before_update()
returns trigger
language plpgsql
as $$
begin
  if public.is_finance_staff() and public.invoice_status() = 'draft'
     and new.status is distinct from 'draft'
     and new.status is distinct from 'sent'
  then
    raise exception 'draft status must go to sent';
  end if;

  if not public.is_finance_staff()
     and public.invoice_status() = 'draft'
     and new.status is distinct from 'draft'
     and new.status is distinct from 'sent'
  then
    raise exception 'draft status can only go to sent';
  end if;

  if not public.is_finance_staff()
     and public.invoice_status() in ('sent', 'paid', 'void')
     and (new.customer is distinct from old.customer
          or new.amount is distinct from old.amount)
  then
    raise exception 'only finance staff can change customer or amount';
  end if;

  if not public.is_finance_staff()
     and public.invoice_status() = 'draft'
     and new.status is distinct from 'draft'
     and new.status is distinct from 'sent'
  then
    raise exception 'only finance staff can change draft status';
  end if;

  if not public.is_finance_staff()
     and public.invoice_status() in ('sent', 'paid', 'void')
     and new.status is distinct from old.status
     and new.status not in ('paid', 'void')
  then
    raise exception 'only finance staff can change sent status';
  end if;

  if not public.is_finance_staff()
     and public.invoice_status() in ('sent', 'paid', 'void')
     and new.status is distinct from old.status
     and new.status in ('paid', 'void')
     and old.status is distinct from 'sent'
  then
    raise exception 'only sent invoices can be paid or voided';
  end if;

  if (select public.invoice_can_write()) and new.status is distinct from 'draft'
     and new.status is not distinct from old.status
  then
    raise exception 'only draft invoices can be edited';
  end if;

  if not public.is_finance_staff() and new.created_by is distinct from old.created_by
  then
    raise exception 'creator cannot be changed';
  end if;

  return new;
end;
$$;

create policy invoices_select
on public.invoices
for select
to authenticated
using (public.invoice_readable());

create policy invoices_insert
on public.invoices
for insert
to authenticated
with check (public.invoice_can_write() and created_by = auth.uid());

create policy invoices_update
on public.invoices
for update
to authenticated
using (public.invoice_can_write())
with check (
  public.is_finance_staff()
  or public.invoice_readable()
  and (
    public.invoice_status() = 'draft'
    or (
      public.invoice_status() in ('sent', 'paid', 'void')
      and public.invoice_can_write()
    )
  )
);

create policy invoices_delete
on public.invoices
for delete
to authenticated
using (
  public.is_finance_staff()
  or (
    public.invoice_status() = 'draft'
    and public.invoice_readable()
  )
);

create trigger invoices_before_insert
before insert on public.invoices
for each row execute function public.invoice_before_insert();

create trigger invoices_before_update
before update on public.invoices
for each row execute function public.invoice_before_update();
