stable
as $$
  select coalesce((select created_by from public.invoices where id = coalesce(current_setting('invoice_id')::text, '')::bigint), auth.uid());
$$;

create or replace function public.invoice_status()
returns text
language sql
stable
as $$
  select coalesce(
    (select status from public.invoices where id = coalesce(current_setting('invoice_id')::text, '')::bigint),
    'draft'::text
  );
$$;

create or replace function public.protect_invoices()
returns trigger
language plpgsql
as $$
begin
  if public.is_finance_staff() then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.created_by is distinct from old.created_by
     or new.created_by is distinct from auth.uid() then
    raise exception 'created_by cannot be changed';
  end if;

  if public.invoice_status() = 'draft' then
    if old.status = 'draft' then
      if new.status is distinct from old.status then
        if new.status = 'sent' then
          return new;
        end if;
        raise exception 'draft invoices can only be changed to sent';
      end if;
      return new;
    end if;
    raise exception 'non-draft invoices cannot be changed';
  end if;

  if old.status in ('draft', 'sent') then
    raise exception 'only sent invoices can be changed';
  end if;

  if new.status is distinct from old.status then
    if new.status in ('paid', 'void') then
      return new;
    end if;
    raise exception 'sent invoices can only be changed to paid or void';
  end if;

  if old.status = 'sent' then
    if new.customer is distinct from old.customer
       or new.amount is distinct from old.amount then
      raise exception 'customer and amount cannot be changed on sent invoices';
    end if;
  end if;

  return new;
end;
$$;

