create or replace function public.is_org_member(p_org_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_org_admin(p_org_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
      and m.role = 'admin'
  );
$$;

create or replace function public.invite_org_admin(p_org_id bigint)
returns void
language plpgsql
as $$
begin
  if public.is_org_admin(p_org_id) then
    perform public.is_org_member(p_org_id);
  else
    raise exception 'not an admin of organization %', p_org_id using errcode = '42501';
  end if;
end;
$$;

create policy orgs_select on public.orgs
for select to authenticated
using (public.is_org_member(id));

create policy org_members_select on public.org_members
for select to authenticated
using (public.is_org_member(org_id));

create policy invites_select on public.invites
for select to authenticated
using (public.is_org_admin(org_id));

create policy invites_insert on public.invites
for insert to authenticated
with check (public.invite_org_admin(org_id) and accepted_at is null and expires_at > now());

create policy invites_update on public.invites
for update to authenticated
using (public.invite_org_admin(org_id) and accepted_at is null and expires_at > now())
with check (public.invite_org_admin(org_id) and accepted_at is null and expires_at > now());

create policy invites_delete on public.invites
for delete to authenticated
using (public.invite_org_admin(org_id) and accepted_at is null and expires_at > now());

create or replace function public.accept_invite(p_token text)
returns bigint
language plpgsql
as $$
declare
  v_invites public.invites%rowtype;
  v_org_id bigint;
  v_email text;
  v_role text;
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;

  select * into v_invites
  from public.invites
  where token = p_token;

  if not found then
    raise exception 'unknown token';
  end if;

  if v_invites.accepted_at is not null then
    raise exception 'invite already accepted';
  end if;

  if v_invites.expires_at <= now() then
    raise exception 'invite expired';
  end if;

  v_email := lower(auth.jwt() ->> 'email');
  if v_email is null or v_email <> lower(v_invites.email) then
    raise exception 'email mismatch';
  end if;

  v_org_id := v_invites.org_id;
  v_role := v_invites.role;

  insert into public.org_members (org_id, user_id, role)
  values (v_org_id, auth.uid(), v_role);

  update public.invites
  set accepted_at = now()
  where token = p_token;

  return v_org_id;
end;
$$;

revoke all on public.orgs from anon;
revoke all on public.org_members from anon;
revoke all on public.invites from anon;

revoke all on public.orgs from authenticated;
revoke all on public.org_members from authenticated;
revoke all on public.invites from authenticated;

grant select on public.orgs to authenticated;
grant select on public.org_members to authenticated;
grant select on public.invites to authenticated;

grant insert, update, delete on public.invites to authenticated;

grant usage on sequence public.orgs_id_seq to authenticated;
grant usage on sequence public.org_members_org_id_seq to authenticated;
grant usage on sequence public.invites_token_seq to authenticated;

grant all on public.orgs to service_role;
grant all on public.org_members to service_role;
grant all on public.invites to service_role;

grant usage on sequence public.orgs_id_seq to service_role;
