  and accepted_at is null
  and expires_at > now()
);

create or replace function public.accept_invite(p_token text)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_org_id bigint;
  v_email text;
  v_invited_by uuid;
  v_invited_role text;
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;

  select i.org_id, lower(i.email), i.invited_by, i.role
  into v_org_id, v_email, v_invited_by, v_invited_role
  from public.invites i
  where i.token = p_token
    and i.accepted_at is null
    and i.expires_at > now()
  for update;

  if not found or v_org_id is null then
    raise exception 'unknown or expired token';
  end if;

  if lower(auth.jwt() ->> 'email') <> v_email then
    raise exception 'email mismatch';
  end if;

  insert into public.org_members (org_id, user_id, role)
  values (v_org_id, auth.uid(), v_invited_role);

  update public.invites
  set accepted_at = now()
  where token = p_token;

  return v_org_id;
end;
$$;

create or replace function public.invites_guard()
returns trigger
language plpgsql
as $$
begin
  if coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if not exists (
      select 1 from public.org_members m where m.org_id = new.org_id and m.user_id = auth.uid() and m.role = 'admin'
    ) then
      raise exception 'not an admin of the organization';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if not exists (
      select 1 from public.org_members m where m.org_id = new.org_id and m.user_id = auth.uid() and m.role = 'admin'
    ) then
      raise exception 'not an admin of the organization';
    end if;
    if new.accepted_at is distinct from old.accepted_at or new.expires_at is distinct from old.expires_at then
      raise exception 'cannot change accepted_at or expires_at';
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if not exists (
      select 1 from public.org_members m where m.org_id = old.org_id and m.user_id = auth.uid() and m.role = 'admin'
    ) then
      raise exception 'not an admin of the organization';
    end if;
    return old;
  end if;

  return new;
end;
$$;

create trigger invites_guard
before insert or update or delete on public.invites
for each row execute function public.invites_guard();
