    where m.project_id = p_project_id
      and m.user_id = auth.uid()
      and m.role = 'maintainer'
  );
$$;

create or replace function public.can_view_issue(p_issue_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.issues i
    join public.project_members m on m.project_id = i.project_id
    where i.id = p_issue_id
      and m.user_id = auth.uid()
      and (
        i.is_confidential is false
        or m.role = 'maintainer'
        or i.reporter_id = auth.uid()
        or i.assignee_id = auth.uid()
      )
  );
$$;

create or replace function public.enforce_issue_confidentiality()
returns trigger
language plpgsql
as $$
begin
  if (select public.is_project_maintainer(new.project_id)) then
    return new;
  end if;

  if (new.is_confidential is distinct from old.is_confidential) then
    raise exception 'only maintainers can make an issue confidential';
  end if;

  return new;
end;
$$;

create policy projects_select on public.projects
for select to authenticated
using (public.is_project_member(id));

create policy project_members_select on public.project_members
for select to authenticated
using (public.is_project_member(project_id));

create policy issues_select on public.issues
for select to authenticated
using (public.can_view_issue(id));

create policy issues_insert on public.issues
for insert to authenticated
with check (
  public.is_project_member(project_id)
  and status = 'open'
  and reporter_id = auth.uid()
);

create policy issues_update on public.issues
for update to authenticated
using (public.can_view_issue(id))
with check (
  public.is_project_member(project_id)
  and (
    public.is_project_maintainer(project_id)
    or (not is_confidential and not old.is_confidential)
    or (is_confidential and old.is_confidential)
  )
);

create trigger issues_confidentiality_trigger
before update on public.issues
for each row
execute function public.enforce_issue_confidentiality();
