alter table public.pharmacists enable row level security;
alter table public.prescriptions enable row level security;
alter table public.dispenses enable row level security;

create policy pharmacists_select on public.pharmacists
  for select to authenticated
  using (true);

create policy prescriptions_select on public.prescriptions
  for select to authenticated
  using (
    auth.uid() = (select user_id from public.pharmacists where user_id = auth.uid())
    or patient_id = auth.uid()
    or exists (select 1 from public.pharmacists where user_id = auth.uid())
  );

create policy dispenses_select on public.dispenses
  for select to authenticated
  using (
    exists (select 1 from public.pharmacists where user_id = auth.uid())
    or exists (select 1 from public.prescriptions p where p.id = dispenses.prescription_id and p.patient_id = auth.uid())
  );

create or replace function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_pharmacist uuid := (select user_id from public.pharmacists where user_id = auth.uid());
  v_refills integer;
begin
  if v_pharmacist is null then
    raise exception 'not a pharmacist';
  end if;

  select p.refills_left into v_refills
  from public.prescriptions p
  where p.id = p_prescription_id
  for update;

  if not found then
    raise exception 'prescription not found';
  end if;

  if p_prescription_id = (select user_id from public.pharmacists where user_id = auth.uid()) then
    raise exception 'cannot dispense own prescription';
  end if;

  if v_refills is null or v_refills <= 0 then
    raise exception 'no refills left';
  end if;

  if exists (select 1 from public.prescriptions p where p.id = p_prescription_id and p.expires_at < now()) then
    raise exception 'prescription expired';
  end if;

  update public.prescriptions
  set refills_left = v_refills - 1
  where id = p_prescription_id;

  insert into public.dispenses (prescription_id, pharmacist_id)
  values (p_prescription_id, v_pharmacist);

  return v_refills - 1;
end;
$$;

revoke all on public.pharmacists from anon;
revoke all on public.prescriptions from anon;
revoke all on public.dispenses from anon;

revoke all on public.pharmacists from authenticated;
revoke all on public.prescriptions from authenticated;
revoke all on public.dispenses from authenticated;

grant select on public.pharmacists to authenticated;
grant select on public.prescriptions to authenticated;
grant select on public.dispenses to authenticated;

grant execute on function public.dispense(bigint) to authenticated;

grant all on public.pharmacists to service_role;
grant all on public.prescriptions to service_role;
grant all on public.dispenses to service_role;
