  if v_refills is null then
    raise exception 'prescription refills_left is null';
  end if;

  if v_refills <= 0 then
    raise exception 'no refills left';
  end if;

  if v_refills > 0 and now() > v_reciprocal then
    raise exception 'prescription has expired';
  end if;

  if v_pharmacist is not null and v_pharmacist = auth.uid() then
    raise exception 'cannot dispense own prescription';
  end if;

  update public.prescriptions
  set refills_left = v_refills - 1
  where id = p_prescription_id;

  insert into public.dispenses (prescription_id, pharmacist_id)
  values (p_prescription_id, auth.uid());

