returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_pharmacist uuid := (select p.user_id from public.pharmacists p where p.user_id = auth.uid());
  v_refills integer;
  v_expires timestamptz;
  v_own boolean;
begin
  if not exists (select 1 from public.pharmacists p where p.user_id = v_pharmacist) then
    raise exception 'not a pharmacist';
  end if;

  select p.refills_left, p.expires_at, p.patient_id
  into v_refills, v_expires, v_own
  from public.prescriptions p
  where p.id = p_prescription_id
  for update;

  if not found then
    raise exception 'prescription not found';
  end if;

  if v_refills <= 0 then
    raise exception 'no refills left';
  end if;

  if v_expires < now() then
    raise exception 'prescription expired';
  end if;

  if v_own then
    raise exception 'cannot dispense own prescription';
  end if;

  update public.prescriptions
  set refills_left = refills_left - 1
  where id = p_prescription_id
  returning refills_left into v_refills;

  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, v_pharmacist, now());

  return v_refills;
end;
$$;

