create or replace function public.is_assigned(p_project_id bigint, p_lang text)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.translators t
    where t.project_id = p_project_id
      and t.lang = p_lang
  );
$$;

create or replace function public.is_translator(p_project_id bigint, p_lang text)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.translators t
    where t.project_id = p_project_id
      and t.lang = p_lang
      and t.role = 'translator'
  );
$$;

create or replace function public.is_reviewer(p_project_id bigint, p_lang text)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.translators t
    where t.project_id = p_project_id
      and t.lang = p_lang
      and t.role = 'reviewer'
  );
$$;

create or replace function public.segments_enforce_update()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_project_id bigint := (select s.project_id from public.segments s where s.id = new.id);
  v_lang text := (select s.lang from public.segments s where s.id = new.id);
  v_assigned boolean := public.is_assigned(v_project_id, v_lang);
  v_translator boolean := public.is_translator(v_project_id, v_lang);
  v_reviewer boolean := public.is_reviewer(v_project_id, v_lang);
  v_status text := (select s.status from public.segments s where s.id = new.id);
begin
  if new.id is distinct from old.id
     or new.project_id is distinct from old.project_id
     or new.lang is distinct from old.lang
     or new.source_text is distinct from old.source_text then
    raise exception 'segments cannot be modified in project, language, or source';
  end if;

  if new.status is distinct from old.status then
    if v_status = 'reviewed' then
      raise exception 'reviewed segments cannot be changed';
    end if;

    if new.status = 'reviewed' then
      if not v_reviewer then
        raise exception 'only reviewers can mark segments reviewed';
      end if;
      new.translated_by := null;
    elsif new.status = 'draft' then
      if not v_assigned then
        raise exception 'only assigned users can edit segments';
      end if;
      if v_translator then
        new.translated_by := auth.uid();
      end if;
    else
      raise exception 'invalid segment status';
    end if;
  elsif new.target_text is distinct from old.target_text then
    if v_status = 'reviewed' then
      raise exception 'reviewed segments cannot be changed';
    end if;

    if not v_assigned then
      raise exception 'only assigned users can edit segments';
    end if;

    if v_translator then
      new.translated_by := auth.uid();
    elsif v_reviewer then
      new.translated_by := null;
    end if;
  end if;

  return new;
end;
$$;

create trigger segments_enforce_update
before update on public.segments
for each row execute function public.segments_enforce_update();

create policy projects_select_assigned
on public.projects
for select
to authenticated
using (public.is_assigned(id, (select t.lang from public.translators t where t.project_id = id)));

create policy translators_select_assigned
on public.translators
for select
to authenticated
using (public.is_assigned(project_id, (select t.lang from public.translators t where t.project_id = public.translators.project_id)));

create policy segments_select_assigned
on public.segments
for select
to authenticated
using (public.is_assigned(project_id, lang));

create policy segments_update_assigned
on public.segments
for update
to authenticated
using (
  public.is_assigned(project_id, lang)
  and (
    (public.is_translator(project_id, lang) and status = 'draft')
    or (public.is_reviewer(project_id, lang) and status = 'draft')
  )
)
with check (
  public.is_assigned(project_id, lang)
  and (
    (public.is_translator(project_id, lang) and status = 'draft')
    or (public.is_reviewer(project_id, lang) and status in ('draft', 'reviewed'))
  )
);

revoke all on public.projects from anon;
revoke all on public.translators from anon;
revoke all on public.segments from anon;

revoke all on public.projects from authenticated;
revoke all on public.translators from authenticated;
revoke all on public.segments from authenticated;

grant select on public.projects to authenticated;
grant select on public.translators to authenticated;
grant select on public.segments to authenticated;

grant update (target_text, translated_by, status) on public.segments to authenticated;
