create or replace function public.protected_segments_guard()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'INSERT' then
    raise exception 'segments cannot be created through the app';
  end if;
  if tg_op = 'DELETE' then
    raise exception 'segments cannot be deleted through the app';
  end if;
  if new.project_id is distinct from old.project_id
     or new.status is distinct from old.status
     or new.lang is distinct from old.lang
     or new.source_text is distinct from old.source_text then
    raise exception 'protected segment fields cannot be changed';
  end if;
  return new;
end;
$$;

create or replace function public.segments_select()
returns setof public.segments
language sql
stable
as $$
  select s.*
  from public.segments s
  join public.projects p on p.id = s.project_id
  where public.is_assigned(s.project_id, s.lang);
$$;

create or replace function public.segments_insert()
returns trigger
language plpgsql
as $$
declare
  l_project bigint := new.project_id;
  l_lang text := new.lang;
begin
  if not public.is_assigned(l_project, l_lang) then
