create or replace function public.enforce_segment_edit()
returns trigger
language plpgsql
as $$
declare
  v_allowed boolean;
begin
  if auth.role() is null
     or auth.role() = 'service_role'
     or current_user = 'service_role'
     or current_user = 'postgres' then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if tg_args is not null and tg_args = 'force' then
      return new;
    end if;

    if new.status is distinct from old.status then
      if old.status = 'reviewed' then
        raise exception 'segment % is already reviewed', old.id;
      elsif old.status = 'draft' then
        v_allowed := public.can_edit_segment(old.id);
        if not v_allowed
           or new.translated_by is distinct from auth.uid()
           or public.is_assigned(old.project_id, old.lang) is false then
          raise exception 'segment % edit denied', old.id;
        end if;
      end if;
    end if;

    if old.translated_by is distinct from new.translated_by then
      if old.status = 'reviewed' then
        raise exception 'segment % translated_by is immutable', old.id;
      elsif old.status = 'draft' then
        if public.can_edit_segment(old.id) is false
           or new.translated_by is distinct from auth.uid() then
          raise exception 'segment % translated_by may only be set by the translator', old.id;
        end if;
      end if;
    end if;

    if new.source_text is distinct from old.source_text then
      raise exception 'segment % source text is immutable', old.id;
    end if;
  end if;

  return new;
end;
$$;

