create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_status text;
  v_signer uuid := auth.uid();
  v_order integer;
  v_earliest_unsigned integer;
begin
  if v_signer is null then
    raise exception 'not authenticated';
  end if;

  select e.status, r.sign_order
    into v_status, v_order
    from public.envelopes e
    join public.envelope_recipients r on r.envelope_id = e.id
   where e.id = p_envelope_id
   order by r.sign_order
   limit 1;

  if not found then
    raise exception 'envelope not found';
  end if;

  if v_status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  if v_order is null then
    raise exception 'not a recipient';
  end if;

  if exists (
    select 1 from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.sign_order < v_order
      and r.signed_at is null
  ) then
    raise exception 'earlier recipient has not signed';
  end if;

  if exists (
    select 1 from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.user_id = v_signer
      and r.signed_at is not null
  ) then
    raise exception 'already signed';
  end if;

  update public.envelope_recipients
     set signed_at = now()
   where envelope_id = p_envelope_id
     and user_id = v_signer;

  select count(*) into v_earliest_unsigned
    from public.envelope_recipients
   where envelope_id = p_envelope_id
     and signed_at is null;

  if v_earliest_unsigned = 0 then
    update public.envelopes
       set status = 'completed'
     where id = p_envelope_id;
  end if;

  select status into v_status
    from public.envelopes
   where id = p_envelope_id;

  return v_status;
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_status text;
  v_signer uuid := auth.uid();
begin
  if v_signer is null then
    raise exception 'not authenticated';
  end if;

  select e.status, e.sender_id
    into v_status, v_signer
    from public.envelopes e
   where e.id = p_envelope_id;

  if not found then
    raise exception 'envelope not found';
  end if;

  if v_status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  if v_signer is null or v_signer = '' then
    raise exception 'envelope has no sender';
  end if;

  if v_signer <> (select auth.uid()) then
    raise exception 'only the sender can void the envelope';
  end if;

  update public.envelopes
     set status = 'voided'
   where id = p_envelope_id;

  select status into v_status
    from public.envelopes
   where id = p_envelope_id;

  return v_status;
end;
$$;

