  where r.envelope_id = public.envelopes.id and r.user_id = (select auth.uid())
));

create policy envelope_recipients_select
on public.envelope_recipients
for select
to authenticated
using (exists (
  select 1 from public.envelopes e
  where e.id = envelope_recipients.envelope_id
    and (e.sender_id = (select auth.uid())
         or exists (
           select 1 from public.envelope_recipients r
           where r.envelope_id = e.id and r.user_id = (select auth.uid())
         ))
));

create or replace function public.sign_envelope(p_envelope_id bigint) returns text
language plpgsql
as $$
declare
  v_envelope_status text;
  v_signer_user_id uuid := (select auth.uid());
  v_sign_order integer;
  v_earlier_signed boolean;
  v_recipient_count integer;
  v_signed_count integer;
begin
  if v_signer_user_id is null then
    raise exception 'not authenticated';
  end if;

  select e.status, r.sign_order
  into v_envelope_status, v_sign_order
  from public.envelopes e
  join public.envelope_recipients r on r.envelope_id = e.id
  where e.id = p_envelope_id
  and r.user_id = v_signer_user_id
  order by r.sign_order
  limit 1;

  if not found or v_envelope_status is null then
    raise exception 'not a recipient';
  end if;

  if v_envelope_status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id
    and user_id = v_signer_user_id
    and signed_at is null;

  if not found then
    raise exception 'already signed';
  end if;

  select count(*), count(case when signed_at is not null then 1 end)
  into v_recipient_count, v_signed_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id;

  if v_signed_count >= v_recipient_count then
    update public.envelopes set status = 'completed' where id = p_envelope_id;
  end if;

  return (select status from public.envelopes where id = p_envelope_id);
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint) returns text
language plpgsql
as $$
declare
  v_envelope_status text;
  v_sender_user_id uuid := (select auth.uid());
begin
  if v_sender_user_id is null then
    raise exception 'not authenticated';
  end if;

  select e.status, e.sender_id
  into v_envelope_status, v_sender_user_id
  from public.envelopes e
  where e.id = p_envelope_id
  limit 1;

  if not found or v_envelope_status is null then
    raise exception 'envelope not found';
  end if;

  if v_envelope_status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  if v_sender_user_id <> (select auth.uid()) then
    raise exception 'not the sender';
  end if;

  update public.envelopes set status = 'voided' where id = p_envelope_id;

  return (select status from public.envelopes where id = p_envelope_id);
end;
$$;

revoke all on public.envelopes from anon;
revoke all on public.envelope_recipients from anon;
revoke all on public.envelopes from authenticated;
revoke all on public.envelope_recipients from authenticated;

grant select on public.envelopes to authenticated;
grant select on public.envelope_recipients to authenticated;
grant execute on function public.sign_envelope(bigint) to authenticated;
grant execute on function public.void_envelope(bigint) to authenticated;

grant usage on schema public to authenticated;
