create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_status text;
  v_order integer;
  v_signer uuid;
  v_signed bool;
begin
  if auth.role() is null then
    raise exception 'not authenticated';
  end if;

  select e.status, r.sign_order, r.user_id
    into v_status, v_order, v_signer
    from public.envelopes e
    join public.envelope_recipients r on r.envelope_id = e.id
   where e.id = p_envelope_id
   order by r.sign_order
   limit 1;

  if not found then
    raise exception 'envelope does not exist or is not sent';
  end if;

  if v_status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  if auth.uid() <> v_signer then
    raise exception 'not a recipient of this envelope';
  end if;

  if exists (select 1 from public.envelope_recipients r
               where r.envelope_id = p_envelope_id
                 and r.user_id = auth.uid()
                 and r.signed_at is not null) then
    raise exception 'already signed';
  end if;

  if exists (select 1 from public.envelope_recipients r
               where r.envelope_id = p_envelope_id
                 and r.sign_order < v_order
                 and r.signed_at is null) then
    raise exception 'earlier recipients have not signed yet';
  end if;

  update public.envelope_recipients
     set signed_at = now()
   where envelope_id = p_envelope_id
     and user_id = auth.uid();

  return (select e.status
            from public.envelopes e
           where e.id = p_envelope_id);
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_status text;
  v_sender uuid;
begin
  if auth.role() is null then
    raise exception 'not authenticated';
  end if;

  select e.status, e.sender_id
    into v_status, v_sender
    from public.envelopes e
   where e.id = p_envelope_id
   limit 1;

  if not found then
    raise exception 'envelope does not exist';
  end if;

  if v_status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  if auth.uid() <> v_sender then
    raise exception 'only the sender can void this envelope';
  end if;

  update public.envelopes
     set status = 'voided'
   where id = p_envelope_id
     and status = 'sent';

  return (select e.status
            from public.envelopes e
           where e.id = p_envelope_id);
end;
$$;

