alter table public.reviewers enable row level security;
alter table public.proposals enable row level security;
alter table public.reviews enable row level security;

create or replace function public.is_reviewer()
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.reviewers r
    where r.user_id = auth.uid()
  );
$$;

create or replace function public.is_proposal_speaker(p_proposal_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.proposals p
    where p.id = p_proposal_id
      and p.speaker_id = auth.uid()
  );
$$;

create or replace function public.proposal_undecided(p_proposal_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.proposals p
    where p.id = p_proposal_id
      and p.status = 'submitted'
  );
$$;

create or replace function public.reviewer_review_own_proposal(p_proposal_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.reviews r
    where r.proposal_id = p_proposal_id
      and r.reviewer_id = auth.uid()
  );
$$;

create or replace function public.reviewer_review_undecided_proposal(p_proposal_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.proposals p
    join public.reviews r on r.proposal_id = p.id
    where p.id = p_proposal_id
      and p.status = 'submitted'
      and r.reviewer_id = auth.uid()
  );
$$;

create or replace function public.reviews_enforce_proposal_undecided()
returns trigger
language plpgsql
as $$
begin
  if public.proposal_undecided(new.proposal_id) then
    return new;
  end if;
  raise exception 'reviews can only be submitted for undecided proposals';
end;
$$;

create or replace function public.proposals_enforce_speaker_or_reviewer()
returns trigger
language plpgsql
as $$
declare
  v_is_reviewer boolean := public.is_reviewer();
  v_is_speaker  boolean := public.is_proposal_speaker(new.id);
begin
  if v_is_reviewer then
    return new;
  end if;
  if v_is_speaker and new.status = 'submitted' then
    return new;
  end if;
  raise exception 'proposals can only be edited by their speaker while undecided';
end;
$$;

create or replace function public.reviews_enforce_reviewer_or_decision()
returns trigger
language plpgsql
as $$
declare
  v_is_reviewer boolean := public.is_reviewer();
  v_is_speaker  boolean := public.is_proposal_speaker(new.proposal_id);
  v_reviewer_id uuid := auth.uid();
begin
  if v_is_reviewer then
    if public.reviewer_review_own_proposal(new.proposal_id) then
      raise exception 'reviewers cannot review their own proposals';
    end if;
    if not public.reviewer_review_undecided_proposal(new.proposal_id) then
      raise exception 'reviewers can only review undecided proposals';
    end if;
    return new;
  end if;
  if v_is_speaker then
    return new;
  end if;
  raise exception 'reviews are only visible to proposal speakers or reviewers';
end;
$$;

create or replace function public.reviews_enforce_reviewer_own_review()
returns trigger
language plpgsql
as $$
begin
  if public.is_reviewer() and new.reviewer_id <> auth.uid() then
    raise exception 'reviewers can only edit their own reviews';
  end if;
  return new;
end;
$$;

create policy reviewers_select on public.reviewers
  for select to authenticated
  using (user_id = auth.uid());

create policy proposals_select on public.proposals
  for select to authenticated
  using (public.is_reviewer() or public.is_proposal_speaker(id));

create policy proposals_insert on public.proposals
  for insert to authenticated
  with check (public.is_reviewer() or (public.is_proposal_speaker(id) and status = 'submitted'));

create policy proposals_update on public.proposals
  for update to authenticated
  using (public.is_reviewer() or (public.is_proposal_speaker(id) and public.proposal_undecided(id)))
  with check (public.is_reviewer() or (public.is_proposal_speaker(id) and public.proposal_undecided(id)));

create policy reviews_select on public.reviews
  for select to authenticated
  using (public.is_reviewer() or (public.is_proposal_speaker(proposal_id) and public.proposal_undecided(proposal_id)));

create policy reviews_insert on public.reviews
  for insert to authenticated
  with check (
    public.is_reviewer()
    and public.proposal_undecided(proposal_id)
    and not public.reviewer_review_own_proposal(proposal_id)
    and not public.reviewer_review_undecided_proposal(proposal_id)
  );

create policy reviews_update on public.reviews
  for update to authenticated
  using (
    public.is_reviewer()
    and public.proposal_undecided(proposal_id)
    and public.reviewer_review_undecided_proposal(proposal_id)
  )
  with check (
    public.is_reviewer()
    and public.proposal_undecided(proposal_id)
    and public.reviewer_review_undecided_proposal(proposal_id)
  );

create trigger reviews_enforce_proposal_undecided
  before insert or update on public.reviews
  for each row execute function public.reviews_enforce_proposal_undecided();

create trigger proposals_enforce_speaker_or_reviewer
  before insert or update on public.proposals
  for each row execute function public.proposals_enforce_speaker_or_reviewer();

create trigger reviews_enforce_reviewer_or_decision
  before insert or update on public.reviews
  for each row execute function public.reviews_enforce_reviewer_or_decision();

create trigger reviews_enforce_reviewer_own_review
  before update on public.reviews
  for each row execute function public.reviews_enforce_reviewer_own_review();
