create or replace function public.resident_unit_id()
returns bigint
language sql
stable
as $$
  select r.unit_id from public.residents r where r.user_id = auth.uid()
$$;

create or replace function public.permit_valid_until(new_valid_until date)
returns boolean
language sql
immutable
as $$
  select new_valid_until is not null
     and new_valid_until >= current_date
     and new_valid_until <= current_date + interval '365 days';
$$;

create policy residents_select on public.residents
  for select to authenticated
  using (user_id = auth.uid());

create policy hoa_admins_select on public.hoa_admins
  for select to authenticated
  using (user_id in (select user_id from public.hoa_admins));

create policy permits_select on public.permits
  for select to authenticated
  using (public.resident_unit_id() is not null and unit_id = public.resident_unit_id()
     or exists (select 1 from public.hoa_admins where user_id = auth.uid()));

create policy permits_insert on public.permits
  for insert to authenticated
  with check (
    public.resident_unit_id() is not null
    and unit_id = public.resident_unit_id()
    and not exists (
      select 1
      from public.permits
      where unit_id = public.resident_unit_id()
        and not revoked
        and valid_until >= current_date
      limit 2
    )
    and public.permit_valid_until(valid_until)
    and not revoked
  );

create policy permits_update on public.permits
  for update to authenticated
  using (public.resident_unit_id() is not null and unit_id = public.resident_unit_id()
     or exists (select 1 from public.hoa_admins where user_id = auth.uid()))
  with check (
    public.resident_unit_id() is not null
    and unit_id = public.resident_unit_id()
    and public.permit_valid_until(valid_until)
    and revoked is distinct from public.permits.revoked
  );

create policy hoa_admins_revoke_permits on public.permits
  for update to authenticated
  using (exists (select 1 from public.hoa_admins where user_id = auth.uid()))
  with check (
    exists (select 1 from public.hoa_admins where user_id = auth.uid())
    and revoked = true
  );

create or replace function public.permits_revocation_protect()
returns trigger
language plpgsql
as $$
begin
  if new.revoked is distinct from old.revoked
     and coalesce(
       (select exists (select 1 from public.hoa_admins where user_id = auth.uid())),
       false
     ) then
    return new;
  end if;
  if new.revoked is distinct from old.revoked then
    raise exception 'only hoa admins can change permit revocation';
  end if;
  return new;
end;
$$;

create trigger permits_revocation_protect
before update on public.permits
for each row execute function public.permits_revocation_protect();
