with check (
  exists (select 1 from public.residents r where r.unit_id = permits.unit_id and r.user_id = auth.uid())
  and (
    select count(*)::bigint from public.permits p
    where p.unit_id = permits.unit_id and not p.revoked and p.valid_until >= current_date
  ) < 2
  and public.permit_valid_until(permits.valid_until) is not null
  and permits.revoked is distinct from old.permits.revoked
  and permits.valid_until is distinct from old.permits.valid_until
  and permits.revoked = true or (
    exists (select 1 from public.hoa_admins where user_id = auth.uid())
    or permits.revoked = false
  )
);

create policy permits_revoke on public.permits
for update to authenticated
using (
  exists (select 1 from public.hoa_admins where user_id = auth.uid())
  or auth.role() = 'service_role'
)
with check (
  public.permit_revoke_whitelist()
  and public.permit_revoke_rls()
);

