```sql
alter table public.residents enable row level security;
alter table public.hoa_admins enable row level security;
alter table public.permits enable row level security;

create or replace function public.resident_unit_id()
returns bigint
language sql
stable
as $$
  select r.unit_id from public.residents r where r.user_id = auth.uid()
$$;

create or replace function public.permit_valid_until(new_valid_until date)
returns trigger
language plpgsql
as $$
begin
  if new_valid_until is null or new_valid_until < current_date or new_valid_until > current_date + interval '365 days' then
    raise exception 'valid_until must be today or later and at most 365 days from now';
  end if;
  return new;
end;
$$;

create or replace function public.permit_revoke_guard()
returns trigger
language plpgsql
as $$
begin
  if new.revoked is distinct from old.revoked and old.revoked = false and new.revoked = true
     and (select auth.role()) is distinct from 'service_role' and (select public.resident_unit_id()) is distinct from old.unit_id then
    raise exception 'only the permit holder may revoke';
  end if;
  if new.revoked is distinct from old.revoked and old.revoked = true and new.revoked = false
     and (select auth.role()) is distinct from 'service_role' then
    raise exception 'revoked permits cannot be un-revoked';
  end if;
  return new;
end;
$$;

create or replace function public.permit_active_count(p_unit_id bigint)
returns integer
language sql
stable
as $$
  select count(*) from public.permits where unit_id = p_unit_id and not revoked and valid_until >= current_date
$$;

create or replace function public.permit_hook()
returns trigger
language plpgsql
as $$
declare
  v_role text := (select auth.role());
  v_unit bigint := null;
  v_resident_count integer;
begin
  if v_role = 'service_role' then
    if tg_op = 'INSERT' then
      return new;
    end if;
    if tg_op = 'UPDATE' then
      return new;
    end if;
    if tg_op = 'DELETE' then
      raise exception 'permits cannot be deleted';
    end if;
  end if;

  if tg_op = 'INSERT' then
    if v_role not in ('service_role', 'authenticated') then
      raise exception 'only authenticated users may insert permits';
    end if;
    v_unit := new.unit_id;
    v_resident_count := public.permit_active_count(v_unit);
    if v_resident_count >= 2 then
      raise exception 'unit has 2 active permits already';
    end if;
    if v_role = 'authenticated' then
      if v_unit is null or v_unit not in (select unit_id from public.residents where user_id = auth.uid()) then
        raise exception 'only the permit holder may add permits for their unit';
      end if;
    end if;
    new.revoked := false;
    new.valid_until := public.permit_valid_until(new.valid_until);
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if v_role = 'authenticated' then
      v_unit := public.resident_unit_id();
      if v_unit is null then
        raise exception 'only residents may update permits';
      end if;
      if new.unit_id is distinct from old.unit_id then
        raise exception 'unit cannot be changed';
      end if;
      if new.valid_until is distinct from old.valid_until then
        raise exception 'valid_until cannot be changed';
      end if;
      if new.revoked is distinct from old.revoked then
        raise exception 'revocation cannot be changed';
      end if;
      if old.revoked = false and new.revoked = false then
        if public.permit_active_count(v_unit) >= 2 then
          raise exception 'unit has 2 active permits already';
        end if;
      end if;
    elsif v_role = 'admin' then
      if old.revoked = false and new.revoked = false then
        raise exception 'only revocation is allowed';
      end if;
      if old.revoked = true and new.revoked = true then
        raise exception 'only un-revocation is allowed';
      end if;
      if old.revoked = true and new.revoked = false then
        raise exception 'revoked permits cannot be un-revoked';
      end if;
      if new.revoked = true then
        new.valid_until := null;
      end if;
    else
      raise exception 'only authenticated users and admins may update permits';
    end if;
    return new;
  end if;

  return new;
end;
$$;

create policy residents_select on public.residents
  for select to authenticated
  using (user_id = auth.uid());

create policy hoa_admins_select on public.hoa_admins
  for select to authenticated
  using (user_id in (select user_id from public.hoa_admins));

create policy permits_select on public.permits
  for select to authenticated
  using (
    (select auth.role()) = 'service_role'
    or (select public.resident_unit_id()) is not null and unit_id = (select public.resident_unit_id())
    or (select auth.role()) = 'admin'
  );

create policy permits_insert on public.permits
  for insert to authenticated
  with check (
    (select auth.role()) = 'service_role'
    or (select public.resident_unit_id()) is not null
    or public.permit_active_count(unit_id) < 2
  )
  using (
    (select auth.role()) = 'service_role'
    or (select public.resident_unit_id()) is not null
  );

create policy permits_update on public.permits
  for update to authenticated
  using (
    (select auth.role()) = 'service_role'
    or (select public.resident_unit_id()) is not null
    or (select auth.role()) = 'admin'
  )
  with check (
    (select auth.role()) = 'service_role'
    or (select public.resident_unit_id()) is not null
    or (select auth.role()) = 'admin'
  );

create policy permits_revoke on public.permits
  for update to authenticated
  using (
    (select auth.role()) = 'service_role'
    or (select public.resident_unit_id()) is not null
    or (select auth.role()) = 'admin'
  )
  with check (
    (select auth.role()) = 'service_role'
    or (select public.resident_unit_id()) is not null
    or (select auth.role()) = 'admin'
  );

create trigger permits_revoke_check
before update on public.permits
for each row
execute function public.permit_revoke_guard();

create trigger permits_hook
