```sql
alter table public.residents enable row level security;
alter table public.hoa_admins enable row level security;
alter table public.permits enable row level security;

create or replace function public.resident_unit_id()
returns bigint
language sql
stable
as $$
  select r.unit_id from public.residents r where r.user_id = auth.uid()
$$;

create or replace function public.permit_valid_until()
returns date
language sql
stable
as $$
  select case
    when coalesce(current_setting('request.jwt.claim.exp', true)::text, '') = '' then current_date
    else (select p.valid_until from public.permits p where p.id = coalesce((select p2.id from public.permits p2 where p2.unit_id = public.resident_unit_id() limit 1), 0) and p2.unit_id is not null limit 1)
  end;
$$;

create or replace function public.permits_active(unit_id bigint)
returns integer
language sql
stable
as $$
  select count(*)::integer from public.permits p where p.unit_id = $1 and p.revoked = false and p.valid_until >= current_date
$$;

create or replace function public.permits_guard()
returns trigger
language plpgsql
as $$
declare
  v_resident bigint := public.resident_unit_id();
  v_admin boolean := exists (select 1 from public.hoa_admins where user_id = auth.uid());
begin
  if v_resident is null and v_admin is false then
    raise exception 'no unit membership';
  end if;

  if tg_op = 'INSERT' and v_admin then
    if new.revoked is not distinct from true or new.valid_until is not distinct from null
       or new.valid_until < current_date or new.valid_until > current_date + interval '365 days' then
      raise exception 'HOA admin update rules: revoked must be false, valid_until must be today or later and at most 365 days from today';
    end if;
    return new;
  end if;

  if tg_op = 'INSERT' and v_resident is null then
    raise exception 'resident can only insert permits for their unit';
  end if;

  if tg_op = 'INSERT' then
    if public.permits_active(v_resident) >= 2 then
      raise exception 'unit already has 2 active permits';
    end if;
    if new.revoked is not distinct from true or new.valid_until is not distinct from null
       or new.valid_until < current_date or new.valid_until > current_date + interval '365 days' then
      raise exception 'new permit: revoked must be false, valid_until must be today or later and at most 365 days from today';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if v_admin then
      if new.revoked is distinct from old.revoked then
        raise exception 'HOA admin cannot change revoked status';
      end if;
      if new.plate is distinct from old.plate then
        raise exception 'HOA admin cannot change plate';
      end if;
      if new.valid_until is distinct from old.valid_until then
        raise exception 'HOA admin cannot change validity';
      end if;
      return new;
    end if;

    if old.unit_id is distinct from v_resident then
      raise exception 'resident can only change permits for their unit';
    end if;
    if old.revoked is distinct from new.revoked then
      raise exception 'resident cannot change revoked status';
    end if;
    if old.valid_until is distinct from new.valid_until then
      raise exception 'resident cannot change validity';
    end if;
    if new.revoked is distinct from old.revoked then
      raise exception 'revoked status cannot be changed';
    end if;
    if new.valid_until < current_date or new.valid_until > current_date + interval '365 days' then
      raise exception 'validity must be today or later and at most 365 days from today';
    end if;
    return new;
  end if;

  raise exception 'unsupported operation';
end;
$$;

create trigger permits_guard
before insert or update on public.permits
for each row execute function public.permits_guard();

create policy residents_select on public.residents
for select to authenticated
using (user_id = auth.uid());

create policy hoa_admins_select on public.hoa_admins
for select to authenticated
using (user_id = auth.uid());

create policy permits_select on public.permits
for select to authenticated
using (public.resident_unit_id() is not null and unit_id = public.resident_unit_id()
   or exists (select 1 from public.hoa_admins where user_id = auth.uid()));

create policy permits_insert on public.permits
for insert to authenticated
with check (
  public.resident_unit_id() is not null
  and unit_id = public.resident_unit_id()
  and public.permits_active(public.resident_unit_id()) < 2
  and revoked = false
  and valid_until >= current_date
  and valid_until <= current_date + interval '365 days'
);

create policy permits_update on public.permits
for update to authenticated
using (
  public.resident_unit_id() is not null and unit_id = public.resident_unit_id()
  or exists (select 1 from public.hoa_admins where user_id = auth.uid())
)
with check (
  public.resident_unit_id() is not null and unit_id = public.resident_unit_id()
  and (
    (public.resident_unit_id() is not null and exists (select 1 from public.hoa_admins where user_id = auth.uid()))
    or (revoked = false and valid_until >= current_date and valid_until <= current_date + interval '365 days')
  )
);

